        // v5: a 计时修订 1000ms，三人并列
        raceService.reviseTime(RACE, new ReviseTimeRequest("a", 1000L, 4, "req-time-a"));
        StandingResponse tied = raceService.getResults(RACE);
        assertThat(tied.entries()).extracting(ResultEntryResponse::bib)
