 * @param runners         每名选手的缺失检查点行，按参赛号字典序排列
 */
public record MissingCheckpointsResponse(
        String raceId,
        int version,
        int checkpointCount,
        List<RunnerMissingCheckpointsResponse> runners
) {
}

