    String bib();

    /** 检查点代码。 */
    String checkpointCode();

    /** 检查点顺序，从1连续递增。 */
    int position();

    /** 通过该检查点的累计耗时（毫秒，1~86400000）。 */
    long elapsedMillis();

    /**
     * 排除该计时的医疗暂停ID；非 null 表示该计时提交于医疗暂停区间内，
