public java.util.Map<String, MedicalHoldResumptionRow> findResumptions(
        java.util.Collection<String> holdIds) {
    if (holdIds.isEmpty()) {
        return java.util.Map.of();
    }
    String placeholders = String.join(",", holdIds.stream().map(id -> "?").toList());
    List<MedicalHoldResumptionRow> rows = jdbcTemplate.query(
            "SELECT hold_id, end_at, resumed_by, fit_conclusion, resumed_at "
                    + "FROM medical_hold_resumption WHERE hold_id IN (" + placeholders + ")",
            RESUMPTION_ROW_MAPPER, holdIds.toArray());
    java.util.Map<String, MedicalHoldResumptionRow> byHoldId = new java.util.LinkedHashMap<>();
    for (MedicalHoldResumptionRow row : rows) {
        byHoldId.put(row.holdId(), row);
    }
    return byHoldId;
}

